definitions.source:
defineEnemy('shade', {
  name: 'Тень', body: 'serpent', brain: 'stalker',
  seg: 9, rad: 0.52, spacing: 0.36, hover: 1.2, hp: 70, dmg: 1, wander: 1.8, chase: 3.0, chaseR: 8,
  soul: 0.4, danger: 1, eye: 0.12, eyeGap: 0.15,
  look: { core: '#06030c', rim: '#2b0f47', aura: '#8a2cff' },
  spawn: {
    from: 'sea', priority: 1, every: 4, dist: [14, 30],
    max: (c) => (c.collected < 2 ? 0 : Math.min(3, 1 + Math.floor((c.collected - 2) / 5)) + (c.all ? 1 : 0)),
    onSpawn() { if (!G.firstShade) { G.firstShade = true; toast('Тени просыпаются…', 3000, true); } },
  },
})

defineEnemy('warden', {
  name: 'Страж маяка', body: 'serpent', brain: 'warden', boss: true,
  seg: 16, rad: 1.15, spacing: 0.62, hover: 2.3, hp: 700, dmg: 2, wander: 1.5, chase: 2.6, chaseR: 15,
  soul: 1, danger: 1, eye: 0.24, eyeGap: 0.34, soulEvery: 110, dissolve: 0.35, trailEvery: 0.04,
  riseY: () => world.tower.base + 3,
  look: { core: '#06030c', rim: [0.36, 0.07, 0.52], aura: [0.8, 0.22, 1.0], spikes: 0.07, auraGain: 0.5 },
  downText: 'Страж повержен — зажги маяк!',
  spawn: {
    from: 'guardian',
    onSpawn(f) {
      const h = f.segs[0];
      G.bossCam = 2.6;
      SFX.roar();
      rig.trauma = Math.min(1, rig.trauma + 0.6);
      toast('Страж маяка пробудился!', 3600, true, 3);
      for (let k = 0; k < 40; k++) dust.emit(h.x + rr(-1.5, 1.5), world.tower.base + 0.2, h.z + rr(-1.5, 1.5), rr(-2, 2), rr(1, 4), rr(-2, 2), rr(1, 2), 0.6, 1.6, C.smoke, 0.7, -0.4, 1, 0);
    },
  },
})

defineEnemy('frost_imp', Object.assign({}, IMP, {
  name: 'Ледяной бесёнок', hp: 30, chase: 3.6,
  look: { core: '#040812', rim: [0.12, 0.34, 0.6], aura: [0.45, 0.85, 1.0], eye: [0.7, 1, 1, 4], eyeGlow: [0.2, 0.6, 1, 1.3], death: [0.6, 0.9, 1, 2.6] },
  spawn: Object.assign({}, IMP.spawn, { biomes: ['frost'] }),
}))

defineEnemy('frost_warden', Object.assign({}, WARDEN, {
  name: 'Ледяной страж', hp: 760,
  downText: 'Ледяной страж повержен — зажги маяк!',
  look: { core: '#050913', rim: [0.16, 0.36, 0.66], aura: [0.5, 0.85, 1.0], spikes: 0.1, auraGain: 0.55, eye: [0.75, 1, 1, 4], eyeGlow: [0.25, 0.6, 1, 1.4], death: [0.6, 0.9, 1, 2.6] },
  spawn: {
    from: 'guardian',
    onSpawn(f) {
      const h = f.segs[0];
      G.bossCam = 2.6;
      SFX.roar();
      rig.trauma = Math.min(1, rig.trauma + 0.6);
      toast('Ледяной страж пробудился!', 3600, true, 3);
      for (let k = 0; k < 46; k++) dust.emit(h.x + rr(-1.5, 1.5), world.tower.base + 0.2, h.z + rr(-1.5, 1.5), rr(-2, 2), rr(1, 4), rr(-2, 2), rr(1, 2), 0.5, 1.4, C.spray, 0.8, -0.2, 1, 0);
    },
  },
}))

defineEnemy('uw_kraken', Object.assign({}, WARDEN, { name: 'Хранитель глубин', body: 'swimmer', model: 'kraken_tentacle', len: 8,
  downText: 'Хранитель глубин повержен — зажги маяк!',
  look: { core: [0.02, 0.07, 0.12], rim: [0.2, 0.7, 0.9], aura: [0.3, 0.9, 1.0], death: [0.5, 1, 1, 2.6] },
  spawn: Object.assign({}, WARDEN.spawn, { onSpawn(f) {
    const h = f.segs[0];
    G.bossCam = 2.6; SFX.roar(); rig.trauma = Math.min(1, rig.trauma + 0.6);
    toast('Хранитель глубин пробудился!', 3600, true, 3);
    for (let k = 0; k < 40; k++) dust.emit(h.x + rr(-1.5, 1.5), world.tower.base + 0.2, h.z + rr(-1.5, 1.5), rr(-2, 2), rr(1, 4), rr(-2, 2), rr(1, 2), 0.6, 1.6, C.spray, 0.7, -0.4, 1, 0);
  } }) }))
